        r0,r1=pts[0][0],pts[-1][0]; c0,c1=pts[0][1],pts[-1][1]
        col=pts[0][0]  # topmost-leftmost color value
        d=(1,1) if (r1>r0)==(c1>c0) else (1,-1) if r1>r0 else (-1,1)
