    for v,ps in pts.items():
        mr=sum(p[0]/len(ps) for p in ps); mc=sum(p[1]/len(ps) for p in ps)
        def dist(p): return abs(p[0]-mr)+abs(p[1]-mc)
        far=max(ps,key=dist)
        dr=(far[0]>mr)-(far[0]<mr); dc=(far[1]>mc)-(far[1]<mc)
        rr,cc=far
        while True:
            rr+=dr; cc+=dc
            if not(0<=rr<Hh and 0<=cc<Ww): break
            # only paint if cell is bg or this color (don't overwrite other colors)
            if res[rr][cc]==1 or res[rr][cc]==v:
                res[rr][cc]=v
    return res
