    res=[row[:] for row in g]
    for v,ps in pts.items():
        rs=[p[0] for p in ps]; cs=[p[1] for p in ps]
        mr=sum(rs)/len(ps); mc=sum(cs)/len(ps)
        # direction away from centroid via extreme corners
        for dr,dc in [(1,-1),(-1,1)]:
            if any(p[0]-mr==dr for p in ps) or True:
                pass
        # pick endpoint in each axis
        ends={(max(rs),min(cs)),(max(rs),max(cs)),(min(rs),min(cs)),(min(rs),max(cs))} & set(ps)
        # find actual corners present
        cand=[]
        for e in ends:
            cand.append(e)
        best=None
        for e in cand:
            d=max(abs(e[0]-p[0])+abs(e[1]-p[1]) for p in ps)
            if best is None or d>best[0]: best=(d,e)
        rr,cc=best[1]
        while True:
            rr+=dr; cc+=dc
            if not(0<=rr<Hh and 0<=cc<Ww): break
            if res[rr][cc]==1: res[rr][cc]=v
    return res
